package agy

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// TractorAgentName is the agy custom-agent Tractor provisions and selects
// with `--agent` on every invocation. Selecting it removes agy's native
// file-write tools from the model's toolset entirely, so the model can
// never reach the artifact-path validator that fails a turn after a
// successful workspace write (see nativeWriteTools). The name is Tractor-
// branded and namespaced to make an accidental collision with a user's own
// agy agent implausible; ensureAgentManifest additionally refuses to
// overwrite a manifest at this name that lacks Tractor's marker comment.
const TractorAgentName = "tractor-shell-only"

// tractorAgentMarker is a YAML comment placed at the top of every manifest
// Tractor writes. Its presence is what makes provisioning idempotent and
// safe: ensureAgentManifest only ever overwrites a file that already
// carries this marker (a stale or outdated Tractor manifest); it refuses to
// touch a same-named file that lacks it, since that means a user created
// their own "tractor-shell-only" agent independently.
const tractorAgentMarker = "# tractor-managed-agent: github.com/tylergannon/tractor/harness/agy — do not hand-edit"

// nativeWriteTools are the agy native tools Google's Hooks tool reference
// documents as file-mutating operations capable of carrying ArtifactMetadata
// (write_to_file, multi_replace_file_content) or otherwise performing native
// in-process file writes (replace_file_content). Any of the three can
// trigger agy's "is not a valid artifact path" turn failure for a target
// outside agy's private per-conversation brain/<uuid> directory — the same
// failure harness/agy's repair-retry (isArtifactPathError) recovers from
// reactively. The manifest omits all three from its tools allowlist so the
// model never sees them as callable, and enforceInitTools verifies that
// invariant empirically from agy's own init event rather than trusting the
// manifest file to still say what Tractor thinks it says.
var nativeWriteTools = []string{
	"write_to_file",
	"replace_file_content",
	"multi_replace_file_content",
}

// requiredTool is the tool the manifest must still expose so the model has
// a way to create and edit workspace files: agy's shell/terminal tool.
const requiredTool = "run_command"

// allowedTools is agy 1.1.15's full init.tools baseline (captured empirically
// 2026-08-19 via `agy --output-format stream-json` with no --agent), minus
// nativeWriteTools. It intentionally keeps every other tool agy advertises
// by default — browser automation, MCP, subagents, scheduling, and so on —
// so selecting the Tractor agent changes only the one thing this fix
// targets. Because agy's `tools:` frontmatter is an allowlist, not a
// denylist, this list does not automatically pick up tools a future agy
// release adds; refresh it (and re-run the empirical smoke check in
// ephemeral/worklog/20260819-agy-artifact-prevention.md) when bumping the
// pinned agy version.
var allowedTools = []string{
	"ask_custom_permission",
	"ask_permission",
	"ask_question",
	"browser_click_element",
	"browser_drag_pixel_to_pixel",
	"browser_get_dom",
	"browser_get_network_request",
	"browser_input",
	"browser_list_network_requests",
	"browser_mouse_down",
	"browser_mouse_up",
	"browser_move_mouse",
	"browser_press_key",
	"browser_refresh_page",
	"browser_resize_window",
	"browser_scroll",
	"browser_scroll_dom",
	"browser_select_option",
	"browser_subagent",
	"call_mcp_tool",
	"capture_browser_console_logs",
	"capture_browser_screenshot",
	"click_browser_pixel",
	"command_status",
	"define_subagent",
	"delete_knowledge",
	"execute_browser_javascript",
	"find_by_name",
	"finish",
	"generate_image",
	"grep_search",
	"invoke_subagent",
	"list_browser_pages",
	"list_dir",
	"list_permissions",
	"list_resources",
	"manage_inbox",
	"manage_subagents",
	"manage_task",
	"notebook_edit",
	"notebook_execution",
	"open_browser_url",
	"read_browser_page",
	"read_resource",
	"read_url_content",
	requiredTool,
	"schedule",
	"search_web",
	"sed_file",
	"send_command_input",
	"send_message",
	"view_file",
	"wait",
	"wait_5_seconds",
}

// agentManifestPath returns the global manifest path for the Tractor agent
// under homeDir. Global placement (~/.gemini/config/agents/<name>/agent.md)
// is deliberate over a workspace-local .agents/agents/ manifest: Tractor
// runs branches in per-branch isolated worktrees (engine/artifacts.go,
// added in 2485e4c) each with their own workdir, so a workspace-local
// manifest would need to be provisioned into and cleaned up from every
// branch worktree — and a leftover file would show up in that branch's git
// status and be swept into artifact collection. A single global manifest,
// provisioned once and left in place, sidesteps both problems entirely and
// is invisible to every pipeline workspace.
func agentManifestPath(homeDir string) string {
	return filepath.Join(homeDir, ".gemini", "config", "agents", TractorAgentName, "agent.md")
}

// ensureAgentManifest idempotently provisions Tractor's custom agy agent
// manifest under homeDir and returns the agent name to pass via --agent.
// It is safe to call from multiple processes/adapters concurrently in the
// sense that it always converges to the same canonical content; a lost
// write race just means one writer's identical content wins.
func ensureAgentManifest(homeDir string) (string, error) {
	path := agentManifestPath(homeDir)
	canonical := manifestContent()
	existing, err := os.ReadFile(path)
	if err == nil {
		if string(existing) == canonical {
			return TractorAgentName, nil
		}
		if !strings.Contains(string(existing), tractorAgentMarker) {
			return "", fmt.Errorf(
				"%s already exists and is not Tractor-managed (missing marker comment); "+
					"remove it or rename Tractor's agent (harness/agy.TractorAgentName) to avoid clobbering it",
				path,
			)
		}
		// A stale Tractor-managed manifest (e.g. an older allowedTools
		// baseline); fall through and overwrite with current content.
	} else if !os.IsNotExist(err) {
		return "", fmt.Errorf("read %s: %w", path, err)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return "", fmt.Errorf("create %s: %w", filepath.Dir(path), err)
	}
	if err := os.WriteFile(path, []byte(canonical), 0o644); err != nil {
		return "", fmt.Errorf("write %s: %w", path, err)
	}
	return TractorAgentName, nil
}

func manifestContent() string {
	var b strings.Builder
	b.WriteString("---\n")
	b.WriteString(tractorAgentMarker)
	b.WriteString("\n")
	b.WriteString("name: " + TractorAgentName + "\n")
	b.WriteString("mainAgent: true\n")
	b.WriteString("subagent: false\n")
	b.WriteString("description: >-\n")
	b.WriteString("  Tractor-provisioned agy agent. Omits agy's native file-write tools\n")
	b.WriteString("  (write_to_file, replace_file_content, multi_replace_file_content) so\n")
	b.WriteString("  the model cannot trigger agy's artifact-path validator, which fails a\n")
	b.WriteString("  turn's successful workspace write with \"is not a valid artifact path\"\n")
	b.WriteString("  whenever the target lies outside agy's private brain/<uuid>\n")
	b.WriteString("  directory. Create and edit workspace files exclusively via\n")
	b.WriteString("  run_command.\n")
	b.WriteString("tools:\n")
	for _, tool := range allowedTools {
		b.WriteString("  - " + tool + "\n")
	}
	b.WriteString("---\n\n")
	b.WriteString("Perform all workspace file creation and modification exclusively\n")
	b.WriteString("through run_command (for example a shell heredoc:\n")
	b.WriteString("`cat > <path> <<'EOF' ... EOF`). You do not have a native file-write\n")
	b.WriteString("tool in this session; it is intentionally unavailable because it fails\n")
	b.WriteString("this environment's workspace writes. Do not attempt to invoke one.\n")
	return b.String()
}

// enforceInitTools checks agy's own init event against the invariant the
// Tractor agent manifest is supposed to establish: none of nativeWriteTools
// advertised, requiredTool present. It runs against whatever agy actually
// reports rather than trusting allowedTools/manifestContent, so a manifest
// drift, an agy regression, or a misconfigured --agent flag is caught
// before the model can wander into the broken tool and burn a turn — the
// corroborating research report notes that an *unrecognized* tool
// identifier in a custom agent's allowlist makes agy hang indefinitely, so
// failing fast here on a clear mismatch is safer than discovering it via a
// hung turn.
func enforceInitTools(tools []string) error {
	seen := make(map[string]bool, len(tools))
	for _, tool := range tools {
		seen[tool] = true
	}
	var advertised []string
	for _, forbidden := range nativeWriteTools {
		if seen[forbidden] {
			advertised = append(advertised, forbidden)
		}
	}
	if len(advertised) > 0 {
		return fmt.Errorf(
			"agy advertised native write tool(s) %s despite --agent %s; "+
				"the manifest at ~/.gemini/config/agents/%s/agent.md no longer omits them "+
				"(has it been hand-edited, or does this agy version ignore tools: for a mainAgent?) — "+
				"delete the manifest so Tractor can re-provision it, or pin an agy version where "+
				"the tools: allowlist is honored",
			strings.Join(advertised, ", "), TractorAgentName, TractorAgentName,
		)
	}
	if !seen[requiredTool] {
		return fmt.Errorf(
			"agy did not advertise %q despite --agent %s; "+
				"the manifest at ~/.gemini/config/agents/%s/agent.md must include it in tools: "+
				"or the model has no way to write workspace files — "+
				"delete the manifest so Tractor can re-provision it",
			requiredTool, TractorAgentName, TractorAgentName,
		)
	}
	return nil
}

